package org.eclipse.rdf4j.common.iteration;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.util.ArrayList;
import java.util.Collection;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

import org.junit.jupiter.api.Test;

class IterationsOwnershipTest {
	private static final List<String> VALUES = List.of("first", "second", "first");

	@Test
	void collectorsCloseOnceAndPreserveTheirCollectionSemantics() {
		for (Collector collector : Collector.values()) {
			UnmanagedIteration iteration = new UnmanagedIteration(VALUES, null, null);
			Collection<String> target = collector == Collector.ADD_ALL ? new ArrayList<>() : null;

			Object result = collect(collector, iteration, target);

			assertThat(iteration.closeCount).as("%s closes its input once", collector).isEqualTo(1);
			switch (collector) {
			case AS_LIST -> assertThat(result).isEqualTo(VALUES);
			case AS_SET -> assertThat(result).isEqualTo(new LinkedHashSet<>(VALUES));
			case ADD_ALL -> assertThat(result).isSameAs(target).isEqualTo(VALUES);
			}
		}
	}

	@Test
	void collectorsPreserveReadFailureAndSuppressDistinctCloseFailureExactlyOnce() {
		for (Collector collector : Collector.values()) {
			for (Throwable primary : failures()) {
				for (boolean sameFailure : List.of(true, false)) {
					Throwable closeFailure = sameFailure ? primary : matchingFailureType(primary, "close failure");
					UnmanagedIteration iteration = new UnmanagedIteration(VALUES, primary, closeFailure);

					assertThatThrownBy(() -> collect(collector, iteration,
							collector == Collector.ADD_ALL ? new ArrayList<>() : null))
									.as("%s keeps %s primary when close failure is %s", collector,
											primary.getClass().getSimpleName(),
											sameFailure ? "identical" : "distinct")
									.isSameAs(primary);
					assertThat(iteration.closeCount).as("%s closes once after a read failure", collector).isEqualTo(1);
					assertThat(primary.getSuppressed())
							.containsExactly(sameFailure ? new Throwable[0] : new Throwable[] { closeFailure });
				}
			}
		}
	}

	@Test
	void collectorsPropagateCloseOnlyFailureExactlyOnceIncludingEmptyInputs() {
		for (Collector collector : Collector.values()) {
			for (List<String> values : List.of(VALUES, List.<String>of())) {
				for (Throwable closeFailure : failures()) {
					UnmanagedIteration iteration = new UnmanagedIteration(values, null, closeFailure);

					assertThatThrownBy(() -> collect(collector, iteration,
							collector == Collector.ADD_ALL ? new ArrayList<>() : null))
									.isSameAs(closeFailure);
					assertThat(iteration.closeCount).as("%s closes once on completion", collector).isEqualTo(1);
				}
			}
		}
	}

	@Test
	void addAllKeepsCollectionFailurePrimaryAndSuppressesDistinctCloseFailure() {
		for (Throwable primary : failures()) {
			for (boolean sameFailure : List.of(true, false)) {
				Throwable closeFailure = sameFailure ? primary : matchingFailureType(primary, "close failure");
				UnmanagedIteration iteration = new UnmanagedIteration(VALUES, null, closeFailure);
				Collection<String> rejectingTarget = new ArrayList<>() {
					@Override
					public boolean add(String value) {
						throwUnchecked(primary);
						return false;
					}
				};

				assertThatThrownBy(() -> Iterations.addAll(iteration, rejectingTarget))
						.isSameAs(primary);
				assertThat(iteration.closeCount).isEqualTo(1);
				assertThat(primary.getSuppressed())
						.containsExactly(sameFailure ? new Throwable[0] : new Throwable[] { closeFailure });
			}
		}
	}

	@Test
	void setWithSupplierPreservesReadFailureAndClosesOnceWhenCloseThrowsSameFailure() {
		for (Throwable primary : failures()) {
			UnmanagedIteration iteration = new UnmanagedIteration(VALUES, primary, primary);

			assertThatThrownBy(() -> Iterations.asSet(iteration, LinkedHashSet::new))
					.isSameAs(primary);
			assertThat(iteration.closeCount).isEqualTo(1);
			assertThat(primary.getSuppressed()).isEmpty();
		}
	}

	private static Object collect(Collector collector, CloseableIteration<String> iteration,
			Collection<String> target) {
		return switch (collector) {
		case AS_LIST -> Iterations.asList(iteration);
		case AS_SET -> Iterations.asSet(iteration);
		case ADD_ALL -> Iterations.addAll(iteration, target);
		};
	}

	private static List<Throwable> failures() {
		return List.of(new IllegalStateException("read failure"), new AssertionError("read failure"));
	}

	private static Throwable matchingFailureType(Throwable failure, String message) {
		return failure instanceof Error ? new AssertionError(message) : new IllegalStateException(message);
	}

	private static void throwUnchecked(Throwable failure) {
		if (failure instanceof Error) {
			throw (Error) failure;
		}
		throw (RuntimeException) failure;
	}

	private enum Collector {
		AS_LIST,
		AS_SET,
		ADD_ALL
	}

	private static final class UnmanagedIteration implements CloseableIteration<String> {
		private final List<String> values;
		private final Throwable readFailure;
		private final Throwable closeFailure;
		private int index;
		private int closeCount;

		private UnmanagedIteration(List<String> values, Throwable readFailure, Throwable closeFailure) {
			this.values = values;
			this.readFailure = readFailure;
			this.closeFailure = closeFailure;
		}

		@Override
		public boolean hasNext() {
			if (readFailure != null) {
				throwUnchecked(readFailure);
			}
			return index < values.size();
		}

		@Override
		public String next() {
			return values.get(index++);
		}

		@Override
		public void close() {
			closeCount++;
			if (closeFailure != null) {
				throwUnchecked(closeFailure);
			}
		}
	}
}
